// P1/P2 整 Part 原文归一：无整 Part transcript 且题级 transcript 齐全时，由题级顺序拼接派生（空行分隔），供结果页/专项页整 Part 原文面板使用
(() => {
  for (const test of PET_LISTENING_SAMPLES) {
    const entries = Array.isArray(test.parts)
      ? test.parts.map((p, i) => [String(i + 1), p])
      : Object.entries(test.parts || {});
    for (const [, part] of entries) {
      if (!part || part.transcript) continue;
      const items = part.items || [];
      if (!items.length) continue;
      const segs = items.map((it) => it?.transcript).filter((t) => typeof t === 'string' && t.trim().length > 0);
      if (segs.length === items.length) part.transcript = segs.join('\n\n');
    }
  }
})();
